using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

namespace McpHttpServer;

[McpServerResourceType]
public sealed class ConfigResource
{
    private static readonly Dictionary<string, object> AppConfig = new()
    {
        ["appName"] = "McpHttpServer",
        ["version"] = "1.0.0",
        ["maxRetries"] = 3,
        ["features"] = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["notifications"] = true,
            ["betaAccess"] = false,
        },
    };

    [McpServerResource(
        UriTemplate = "config://app",
        Name = "app-config",
        Description = "Returns the current application configuration as JSON",
        MimeType = "application/json")]
    public static string GetAppConfig()
    {
        return JsonSerializer.Serialize(AppConfig, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(
        UriTemplate = "config://app/features/{featureName}",
        Name = "feature-flag",
        Description = "Returns the status of a specific feature flag")]
    public static string GetFeatureFlag(string featureName)
    {
        if (AppConfig["features"] is Dictionary<string, bool> features
            && features.TryGetValue(featureName, out var enabled))
        {
            return JsonSerializer.Serialize(new { feature = featureName, enabled });
        }

        return JsonSerializer.Serialize(new { feature = featureName, error = "Feature not found" });
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer;

[McpServerToolType]
public sealed class EchoTool
{
    [McpServerTool(Name = "echo"), Description("Echoes the input message back")]
    public static string Echo(string message) => $"Echo: {message}";
}

